@Test
public void testTransformTree(){
  String source = "function test(){\n" +
                   "  var a = 1;\n" +
                   "  return a;\n" +
                   "}";
  AstRoot astRoot = TokenStream.create(source).parse();
  Node irNode = irFactory.transformTree(astRoot, sourceFile, source, config, errorReporter);

  Assert.assertNotNull(irNode);
  FunctionNode functionNode = (FunctionNode) irNode;
  Assert.assertEquals("test", functionNode.getName());
  Scope scope = functionNode.getScope();
  VariableDeclaration variableDeclaration = (VariableDeclaration) scope.getChildAt(0);
  Name name = (Name) variableDeclaration.getChildAt(0);
  Assert.assertEquals("a", name.getName());
  VariableInitializer initializer = variableDeclaration.getChildAt(1);
  NumberLiteral numberLiteral = (NumberLiteral) initializer;
  Assert.assertEquals(1, numberLiteral.getValue().doubleValue());
  ReturnStatement returnStatement = (ReturnStatement) functionNode.getChildAt(2);
  ExpressionStatement expressionStatement = (ExpressionStatement) returnStatement;
  Assert.assertEquals(initializer, expressionStatement.getChildAt(0));
}

