      FunctionPrototypeType functionPrototype = new FunctionPrototypeType(name.substring(4));
      return new FunctionType(functionPrototype);
    } else if (name.startsWith("obj")) {
      InstanceObjectType instanceObject = new InstanceObjectType(name.substring(3), null);
      return instanceObject;
    } else {
      JSTypeNative nativeType = typeRegistry.getNativeType(name);
      return nativeType;
    }
  }
