private FunctionNode createFunctionNode(String source){
  AstRoot root = new AstRoot();
  root.setSourceName("test.js");
  Token[] tokens = tokenize(source);
  root.setTokens(tokens);
  FunctionNode functionNode = (FunctionNode) getFnParamNode(root.getAst());
  Preconditions.checkNotNull(functionNode);
  return functionNode;
}

private Token[] tokenize(String source){
  Token[] tokens = new Token[source.length() + 1];
  int i = 0;
  for (char c : source.toCharArray()) {
    if (c == '\n') {
      tokens[i++] = Token.EOL;
    } else if (c == '/' && source.charAt(i + 1) == '*') {
      int j = i + 2;
      while (j < source.length() && source.charAt(j++) != '*' || j < source.length() - 1 && source.charAt(j++) != '/');
      tokens[i++] = new Token(Token.COMMENT, JSDOC);
    } else {
      tokens[i++] = new Token(c);
    }
  }
  return Arrays.copyOfRange(tokens, 0, i);
}

